template:
@php
    // One form checked twice by the same rules (§17.5): in the browser through FormRules, then by
    // the showcase's door (POST webx/widgets/showcase/validation), which checks them again with the
    // validator. The second button has formnovalidate — it goes straight to the server, so the two
    // can be compared word for word. Every word is the page's: the labels are the validator's
    // names of the fields here and in the door.
    $set = \WebxUi\Widgets\Facades\Widgets::sequence('showcase-validation');
    $labels = [
        'name' => (string) $label_name,
        'email' => (string) $label_email,
        'phone' => (string) $label_phone,
        'age' => (string) $label_age,
        'website' => (string) $label_website,
        'day' => (string) $label_day,
        'password' => (string) $label_password,
        'plan' => (string) $label_plan,
        'photos' => (string) $label_photos,
        'agree' => (string) $label_agree,
    ];
    $rules = \WebxUi\Widgets\Forms\FormRules::for(
        \WebxUi\Widgets\Forms\ShowcaseController::CHECKS,
        \WebxUi\Widgets\Forms\ShowcaseController::attributes($labels),
    );
    $plans = array_filter(['basic' => (string) $plan_basic, 'team' => (string) $plan_team], static fn (string $label): bool => $label !== '');
    $hidden = ['locale' => app()->getLocale(), 'words[heading]' => (string) $thanks_heading, 'words[message]' => (string) $thanks_message];
    foreach ($labels as $short => $label) {
        $hidden["labels[{$short}]"] = $label;
    }
@endphp
<section class="b-showcase-validation" data-wx-block="showcase-validation">
    @if ($heading)
        <h2 class="b-showcase-validation__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-validation__note">{{ $note }}</p>
    @endif
    <div class="b-showcase-validation__frame">
        <x-webx-form :action="route('webx-widgets.showcase.validation')" :id="'showcase-validation-'.$set" :rules="$rules" class="b-showcase-validation__form">
            @foreach ($hidden as $hiddenName => $hiddenValue)
                <input type="hidden" name="{{ $hiddenName }}" value="{{ $hiddenValue }}">
            @endforeach
            <x-webx-field name="check.name" :label="$labels['name']" :hint="(string) $hint_name" autocomplete="name" />
            <x-webx-field name="check.email" type="email" :label="$labels['email']" />
            <x-webx-field name="check.phone" type="tel" :label="$labels['phone']" :hint="(string) $hint_phone" mask />
            <x-webx-field name="check.age" type="number" :label="$labels['age']" optional :optional-label="(string) $optional" />
            <x-webx-field name="check.website" type="url" :label="$labels['website']" optional :optional-label="(string) $optional" />
            <x-webx-field name="check.day" type="date" :label="$labels['day']" />
            <x-webx-field name="check.password" type="password" :label="$labels['password']" :hint="(string) $hint_password" autocomplete="new-password" />
            <x-webx-field name="check.password_confirmation" type="password" :label="(string) $label_confirmation" autocomplete="new-password" />
            @if ($plans !== [])
                <x-webx-field name="check.plan" type="radio" :label="$labels['plan']" :choices="$plans" inline />
            @endif
            <x-webx-field name="check.photos" type="file" :label="$labels['photos']" :hint="(string) $hint_photos" multiple optional :optional-label="(string) $optional" />
            <x-webx-field name="check.agree" type="consent" :label="$labels['agree']" />
            <div class="b-showcase-validation__buttons">
                <x-webx-form.submit>{{ $button }}</x-webx-form.submit>
                <x-webx-form.submit class="b-showcase-validation__server" formnovalidate>{{ $button_server }}</x-webx-form.submit>
            </div>
        </x-webx-form>
    </div>
</section>

styles:
.b-showcase-validation {
    container-type: inline-size;
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-validation__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-validation__note {
    max-width: 42rem;
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-validation__frame {
    max-width: 36rem;
}

.b-showcase-validation__buttons {
    display: flex;
    flex-wrap: wrap;
    gap: var(--site-space-3);
}
